package org.apache.parquet.filter2;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.regex.Pattern;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

  @TempDir
  Path temporaryDirectory;

  @Test
  void runGeneratesCompleteBuilderSourceWithoutDuplicateDeclarations() throws IOException {
    Path generatedFile = temporaryDirectory.resolve(
        "org/apache/parquet/filter2/recordlevel/IncrementallyUpdatedFilterPredicateBuilder.java");
    Files.createDirectories(generatedFile.getParent());

    IncrementallyUpdatedFilterPredicateGenerator generator =
        new IncrementallyUpdatedFilterPredicateGenerator(generatedFile.toFile());

    generator.run();

    String source = Files.readString(generatedFile, StandardCharsets.UTF_8);

    assertTrue(source.startsWith("package org.apache.parquet.filter2.recordlevel;"));
    assertTrue(source.contains(
        "public class IncrementallyUpdatedFilterPredicateBuilder "
            + "extends IncrementallyUpdatedFilterPredicateBuilderBase"));
    assertTrue(source.contains("visit(Eq<T> pred)"));
    assertTrue(source.contains("visit(NotEq<T> pred)"));
    assertTrue(source.contains("visit(In<T> pred)"));
    assertTrue(source.contains("visit(NotIn<T> pred)"));
    assertTrue(source.contains("visit(Lt<T> pred)"));
    assertTrue(source.contains("visit(LtEq<T> pred)"));
    assertTrue(source.contains("visit(Gt<T> pred)"));
    assertTrue(source.contains("visit(GtEq<T> pred)"));
    assertTrue(source.contains("visit(UserDefined<T, U> pred)"));
    assertTrue(source.contains("visit(LogicalNotUserDefined<T, U> notPred)"));

    Pattern duplicateTargetDeclaration = Pattern.compile(
        "(?s).*final (int|long|float|double|Binary) target = .*?;\\s+"
            + "\\1 target = .*?;.*");
    assertFalse(
        duplicateTargetDeclaration.matcher(source).matches(),
        "Generated inequality methods must contain one target declaration per branch");
  }
}

